/bin/bash -lc "cat > /tmp/cpu-chart-browser/lifecycle.mjs <<'EOF'
import {chromium} from 'playwright';
import assert from 'node:assert/strict';
const browser = await chromium.launch({args: ['--no-sandbox']});
const page = await browser.newPage();
const errors = [];
page.on('pageerror', e => errors.push(e.message));
await page.goto('http://localhost:5173');
const result = await page.evaluate(async () => {
  const text = await fetch('/src/CpuChart.tsx').then(r => r.text());
  const main = await fetch('/src/main.tsx').then(r => r.text());
  const url = (text, file) => text.match(new RegExp('\"(/node_modules/.vite/deps/' + file + '["'^"]*)"'"'))[1];
  const React = (await import(url(text, 'react.js'))).default;
  const {createRoot} = (await import(url(main, 'react-dom_client.js'))).default;
  const {ThemeProvider} = await import(url(text, '@gravity-ui_uikit.js'));
  const Yagr = (await import(url(text, '@gravity-ui_yagr.js'))).default;
  const {CpuChart} = await import('/src/CpuChart.tsx');
  let chart;
  const original = Yagr.prototype.setSeries;
  Yagr.prototype.setSeries = function (...args) {chart = this; return original.apply(this, args);};
  const observers = new Set();
  const OriginalObserver = window.ResizeObserver;
  window.ResizeObserver = class extends OriginalObserver {
    observe(...args) {observers.add(this); return super.observe(...args);}
    disconnect() {observers.delete(this); super.disconnect();}
  };
  let reads = 0;
  let activeSubscriptions = 0;
  let notify;
  let snapshot = {timeline: [], values: []};
  const source = {
    getSnapshot() {reads++; return snapshot;},
    subscribe(callback) {activeSubscriptions++; notify = callback; return () => activeSubscriptions--;},
  };
  const container = document.createElement('div');
  container.style.width = '800px';
  document.body.append(container);
  const root = createRoot(container);
  root.render(React.createElement(React.StrictMode, null,
    React.createElement(ThemeProvider, {theme: 'dark'}, React.createElement(CpuChart, {source}))));
  const settle = () => new Promise(r => setTimeout(r, 100));
  await settle();
  const canvas = container.querySelector('canvas');
  const subscriptionsAfterMount = activeSubscriptions;
  const end = Date.now();
  snapshot = {
    timeline: Array.from({length: 43201}, (_, i) => end - 86400000 + i * 2000),
    values: Array.from({length: 43201}, (_, i) => i % 100),
  };
  const previousReads = reads;
  for (let i = 0; i < 1000; i++) notify();
  await settle();
  const burstReads = reads - previousReads;
  const canvasPreserved = canvas === container.querySelector('canvas');
  const points = chart.uplot.data[0].length;
  chart.config.hooks.onSelect[0]({chart, from: end - 100000, to: end - 10000});
  chart.uplot.setScale('x', {min: end - 100000, max: end - 10000});
  notify();
  await settle();
  const zoomPreserved = chart.uplot.scales.x.min === end - 100000 && chart.uplot.scales.x.max === end - 10000;
  snapshot = {timeline: [], values: []};
  notify();
  await settle();
  const emptyCleared = chart.uplot.data[1].every(x => x === null);
  const beforeUnmount = reads;
  notify();
  root.unmount();
  await settle();
  const cleanup = {activeSubscriptions, observers: observers.size, readsAfterUnmount: reads - beforeUnmount, canvases: container.querySelectorAll('canvas').length};
  window.ResizeObserver = OriginalObserver;
  Yagr.prototype.setSeries = original;
  container.remove();
  return {subscriptionsAfterMount, burstReads, canvasPreserved, points, zoomPreserved, emptyCleared, cleanup};
});
console.log(JSON.stringify({result, errors}));
assert.equal(result.subscriptionsAfterMount, 1);
assert.equal(result.burstReads, 1);
assert.equal(result.canvasPreserved, true);
assert.equal(result.points, 43201);
assert.equal(result.zoomPreserved, true);
assert.equal(result.emptyCleared, true);
assert.deepEqual(result.cleanup, {activeSubscriptions: 0, observers: 0, readsAfterUnmount: 0, canvases: 0});
assert.deepEqual(errors, []);
await browser.close();
EOF
